import { MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3, vec4, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight, AmbientLight, AdditiveBlending } = ctx.THREE;

  // Root container
  const root = new Group();

  // Keep track of resources for disposal
  const disposables = [];
  const timelines = [];
  const primitiveInstances = [];

  // Theme Palette
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // 1. SETUP CARD GEOMETRY & MATERIAL
  // Card base dimensions (approx ~3.4 x 2.1 to nicely fill space)
  const cardWidth = 3.6;
  const cardHeight = 2.2;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  disposables.push(cardGeo);

  // Custom Node Material with procedural premium carbon/brushed vertical gradient
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.45,
    transparent: true,
    opacity: 0.95
  });

  // TSL Color Node: vertical gradient from dark surface to subtle ink with accent hint near bottom
  const uvNode = uv();
  const gradNode = mix(
    color(colors.surface),
    color(colors.ink),
    uvNode.y
  );
  cardMat.colorNode = gradNode;
  disposables.push(cardMat);

  const cardMesh = new Mesh(cardGeo, cardMat);
  root.add(cardMesh);

  // 2. ACCENT BORDER (Accent edge on focus/hover)
  const borderGeo = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04, 1, 1);
  const borderMat = new MeshStandardNodeMaterial({
    roughness: 0.1,
    metalness: 0.9,
    transparent: true,
    opacity: 0.15,
  });
  borderMat.colorNode = color(colors.accent);
  disposables.push(borderGeo, borderMat);

  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  root.add(borderMesh);

  // 3. TEXT LAYER (Quote + Attribution)
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.02);
  root.add(textGroup);

  // Get text from config or use high-end default
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let quoteText = "“Form follows precision. The weight of steel, the sweep of the hand—an architecture of seconds.”";
  let attributionText = "— ATELIER JOURNAL";

  if (items.length > 0) {
    quoteText = items[0].text;
    if (items.length > 1) {
      attributionText = items[1].text;
    }
  }

  // Create Quote Text (Lora Serif style implied via styling)
  const quoteObj = ctx.fontAtlas.createText(quoteText, {
    fontSize: 0.14,
    color: colors.paper,
    align: 'center',
    maxWidthPx: 800,
    letterSpacingPx: 1
  });
  quoteObj.position.set(0, 0.2, 0);
  textGroup.add(quoteObj);

  // Create Attribution Text (JetBrains Mono style implied via spacing / styling)
  const attrObj = ctx.fontAtlas.createText(attributionText.toUpperCase(), {
    fontSize: 0.08,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 5
  });
  attrObj.position.set(0, -0.4, 0);
  textGroup.add(attrObj);

  // 4. IMAGE OVERLAY (Using the provided imageUrl if loaded)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // Subtle textured overlay with soft additive mixing to respect ink/dark look
      const overlayGeo = new PlaneGeometry(cardWidth * 0.96, cardHeight * 0.96);
      const overlayMat = new MeshStandardNodeMaterial({
        map: texture,
        transparent: true,
        opacity: 0.12,
        blending: AdditiveBlending,
        roughness: 0.6,
        metalness: 0.2
      });
      disposables.push(overlayGeo, overlayMat);

      const overlayMesh = new Mesh(overlayGeo, overlayMat);
      overlayMesh.position.z = 0.005;
      root.add(overlayMesh);
    }).catch(err => console.warn("Failed to load overlay image:", err));
  }

  // 5. LOCAL LIGHTING (W-PCP §9 lighting rules)
  const ambientLight = new AmbientLight('#ffffff', 0.5);
  root.add(ambientLight);

  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 2, 3);
  root.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-2, -2, 2);
  root.add(localRimLight);

  // 6. INTERACTIONS & ANIMATION
  let isHovered = false;

  const onOver = () => {
    isHovered = true;
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(borderMat);

    // Subtle rise-in effect (+0.15 scene units on hover)
    gsap.to(root.position, {
      y: 0.15,
      z: 0.1,
      duration: 0.4,
      ease: 'power3.out'
    });

    gsap.to(root.scale, {
      x: 1.03,
      y: 1.03,
      duration: 0.4,
      ease: 'power3.out'
    });

    // Illuminate the subtle accent border on focus/hover
    gsap.to(borderMat, {
      opacity: 0.65,
      duration: 0.3
    });
  };

  const onOut = () => {
    isHovered = false;
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(borderMat);

    gsap.to(root.position, {
      y: 0,
      z: 0,
      duration: 0.5,
      ease: 'power2.out'
    });

    gsap.to(root.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.5,
      ease: 'power2.out'
    });

    gsap.to(borderMat, {
      opacity: 0.15,
      duration: 0.5
    });
  };

  const onClick = () => {
    gsap.killTweensOf(root.scale);
    // Press down scale-settle sequence
    const clickTl = gsap.timeline();
    clickTl.to(root.scale, {
      x: 0.96,
      y: 0.96,
      duration: 0.12,
      ease: 'power2.out'
    }).to(root.scale, {
      x: isHovered ? 1.03 : 1.0,
      y: isHovered ? 1.03 : 1.0,
      duration: 0.4,
      ease: 'back.out(1.7)'
    });
    timelines.push(clickTl);

    // Emit target navigation event
    ctx.emit('hub-pricing.select', { card: 'quote' });
  };

  // Register interactive triggers internally on parent
  root.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // 7. CINEMATIC PRIMITIVES
  // Apply parallax-scroll automatically
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const rx = ctx.primitives['parallax-scroll'](root, { intensity: 0.25 });
    if (rx) primitiveInstances.push(rx);
  }

  // 8. LIFECYCLE CLEANUP
  root.userData.cleanup = () => {
    // Kill GSAP
    timelines.forEach(tl => tl.kill());
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(borderMat);

    // Cleanup primitive components
    primitiveInstances.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });

    // Memory release
    disposables.forEach(d => {
      if (typeof d.dispose === 'function') d.dispose();
    });
  };

  return root;
}
